"""The Romanian section of ``analysis/comparison/README.md``.

The README is shared: other language plugins may add their own
sections. This module owns only the text between :data:`BEGIN` and
:data:`END` and leaves everything else byte for byte as it was
(:func:`merge_section`). A README without the markers gets the
section appended; a missing README is created with a short title.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import Final

BEGIN: Final[str] = (
    "<!-- BEGIN romanian_compare: generated by lexpipe.langs.romanian_compare;"
    " edit the code, not this section -->"
)
END: Final[str] = "<!-- END romanian_compare -->"
TITLE: Final[str] = (
    "# Cross-language comparison tables\n\n"
    "Harmonized tables computed by the shared core (`src/lexpipe/`) for "
    "every language (design: `docs/multilingual_design.md`). Each "
    "language plugin maintains its own section below.\n"
)


def merge_section(existing: str | None, body: str) -> str:
    """*existing* README text with the Romanian section set to *body*."""
    block = f"{BEGIN}\n{body.rstrip()}\n{END}\n"
    if existing is None or not existing.strip():
        return f"{TITLE}\n{block}"
    start = existing.find(BEGIN)
    end = existing.find(END, start + 1) if start >= 0 else -1
    if start >= 0 and end >= 0:
        return (
            existing[:start] + block + existing[end + len(END) :].lstrip("\n")
        )
    separator = (
        ""
        if existing.endswith("\n\n")
        else ("\n" if existing.endswith("\n") else "\n\n")
    )
    return existing + separator + block


def table(header: Sequence[str], rows: Sequence[Sequence[str]]) -> list[str]:
    """A Markdown table."""
    lines = ["| " + " | ".join(header) + " |"]
    lines.append("|" + "|".join("---" for _ in header) + "|")
    lines.extend("| " + " | ".join(row) + " |" for row in rows)
    return lines


def fmt(value: str) -> str:
    """CSV cell → table text (empty → "–", floats to 1 decimal)."""
    if value == "":
        return "–"
    if value in ("True", "False"):
        return {"True": "yes", "False": "no"}[value]
    try:
        number = float(value)
    except ValueError:
        return value
    if number.is_integer() and "." not in value:
        return str(int(number))
    return f"{number:.1f}"


def pick(
    rows: Sequence[Mapping[str, str]], **match: str
) -> Mapping[str, str] | None:
    """The single CSV row matching every given column, or None."""
    found = [r for r in rows if all(r.get(k) == v for k, v in match.items())]
    return found[0] if len(found) == 1 else None
